#include "sblr_sec_drop_policy_coordinator.hpp"
#include "api_diagnostics.hpp"
#include <map>
#include <mutex>
namespace scratchbird::engine::internal_api { namespace { std::mutex m; using D=scratchbird::engine::sblr::SblrSecDropPolicyDescriptorV1; std::map<std::string,D> live,used; std::string key(const D&v){return std::string(reinterpret_cast<const char*>(v.descriptor_evidence.data()),v.descriptor_evidence.size());} EngineApiDiagnostic d(std::string c,std::string k){return MakeEngineApiDiagnostic(std::move(c),std::move(k),{});} bool tag(const EngineRequestContext&c,const char*t){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),t)!=c.trace_tags.end();} }
SblrSecDropPolicyCoordinationResult CompileSblrSecDropPolicyDescriptor(const EngineRequestContext&c,const std::string&r,std::uint64_t occurrence,std::uint64_t availability){SblrSecDropPolicyCoordinationResult o;if(!tag(c,"private_sec_drop_policy_binder")||r!=c.statement_uuid.canonical||!occurrence||!availability){o.diagnostic=d("SBLR.OPERAND.INVALID","sblr.sec_drop_policy.coordination_invalid");return o;}o.descriptor.policy_uuid[0]=std::uint8_t(occurrence);o.descriptor.expected_generation=occurrence;o.descriptor.catalog_generation=occurrence;o.descriptor.security_generation=occurrence;o.descriptor.availability=availability;o.descriptor.descriptor_evidence[0]=std::uint8_t(occurrence);std::lock_guard l(m);live[key(o.descriptor)]=o.descriptor;o.ok=true;o.diagnostic=d("OK","ok");return o;}
SblrSecDropPolicyCoordinationResult ConsumeSblrSecDropPolicyDescriptor(const EngineRequestContext&c,const D&v){SblrSecDropPolicyCoordinationResult o;if(!tag(c,"private_sec_drop_policy")){o.diagnostic=d("SECURITY.ACCESS_DENIED","sblr.sec_drop_policy.hidden");return o;}std::lock_guard l(m);auto k=key(v);if(!live.count(k)){o.diagnostic=d(used.count(k)?"MGA.TRANSACTION.STALE":"SECURITY.ACCESS_DENIED",used.count(k)?"sblr.sec_drop_policy.stale":"sblr.sec_drop_policy.hidden");return o;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){o.diagnostic=d("PROCESS.CANCELLED","sblr.sec_drop_policy.cancelled");return o;}used[k]=v;live.erase(k);o.ok=true;o.descriptor=v;o.diagnostic=d("OK","ok");return o;}}
